#pragma once

// Annotations (PLAN.md phase 8d): list, add, change and remove the annotations of a page. What is added
// carries its appearance (/AP), generated by the engine (content/appearance.hpp for markup; an icon for
// notes; the text, in Helvetica, for free text), so that every reader draws it as Capriole does.
//
// Coordinates are the page's as it is shown — points, origin at the top left of the crop box, y down,
// /Rotate applied: those of text::PageText and of a rendering at 72 dpi — and the editor converts them
// into the page's space. Notes and free text stay upright as the page is shown, whatever its /Rotate.
//
// Edits mark only the objects they touch (the annotation, its appearance, the page's /Annots), so an
// incremental save appends just those. As for page operations, a document whose structure needed
// repairs is refused for edits (edit/pages.hpp): save it fully first. Listing works on any document.

#include <array>
#include <cstdint>
#include <optional>
#include <string>
#include <vector>

#include "capriole/core/error.hpp"
#include "capriole/document/document.hpp"
#include "capriole/graphics/geometry.hpp"
#include "capriole/model/object.hpp"

namespace capriole::edit {

enum class AnnotationKind : std::uint8_t {
  kHighlight,  // text markup over boxes of text (quads)
  kUnderline,
  kStrikeOut,
  kSquiggly,
  kNote,      // a sticky note: an icon at rect, its text in contents (/Text)
  kInk,       // freehand strokes
  kSquare,    // a rectangle in rect (/Square)
  kCircle,    // an ellipse in rect (/Circle)
  kLine,      // from → to
  kFreeText,  // text written on the page in rect, wrapped to its width
};

using Rgb = std::array<double, 3>;  // each 0..1

struct AnnotationSpec {
  AnnotationKind kind = AnnotationKind::kHighlight;
  // Geometry, in page coordinates as shown (see above).
  std::vector<graphics::Rect> quads;                  // markup: one box per word or line of text
  std::vector<std::vector<graphics::Point>> strokes;  // ink
  graphics::Rect rect;                                // note (where its icon goes), square, circle, free text
  graphics::Point from;                               // line
  graphics::Point to;
  Rgb color{1, 0.82, 0};    // the colour (/C; the text's colour for free text)
  std::optional<Rgb> fill;  // the interior of a square or circle (/IC)
  double width = 1;         // border or pen, in points
  double opacity = 1;       // /CA
  double font_size = 12;    // free text
  std::string contents;     // UTF-8: the note's text, the free text, a comment on the others
  std::string author;       // UTF-8, /T
  std::string date;         // a PDF date ("D:20261002120000Z") for /M and /CreationDate; none when empty
};

struct AnnotationInfo {
  std::optional<model::ObjectRef> ref;  // none: a direct object in /Annots (listed, not editable)
  std::string subtype;                  // /Subtype, as written
  graphics::Rect rect;                  // as shown (see above)
  std::string contents;                 // UTF-8
  std::string author;                   // UTF-8
  std::optional<Rgb> color;             // /C when it has three components
  bool hidden = false;                  // /F Hidden or NoView
  bool editable = false;                // the editor can move it, change its text and colour, remove it
};

// The annotations of page page_index (from 0), in /Annots order, without popups (they belong to their
// parent annotation).
[[nodiscard]] Result<std::vector<AnnotationInfo>> list_annotations(Document& document, std::uint32_t page_index);

// Adds an annotation to page page_index; returns its reference. kOutOfRange for a page past the last;
// kUnsupported for a geometry the kind needs that is missing (no quads for markup, no stroke for ink,
// an empty rect).
[[nodiscard]] Result<model::ObjectRef> add_annotation(Document& document, std::uint32_t page_index, const AnnotationSpec& spec);

struct AnnotationChange {
  std::optional<graphics::Point> move_by;  // in page coordinates as shown
  std::optional<std::string> contents;     // UTF-8
  std::optional<Rgb> color;
  std::optional<double> opacity;
  std::string date;  // for /M; none when empty
};

// Changes annotation ref of page page_index: moves it (its appearance with it), changes its text or its colour (the
// appearance is generated again for the kinds the editor makes; kUnsupported for another kind's colour).
// Form widgets are fields' (phase 8e): kUnsupported.
[[nodiscard]] Result<void> update_annotation(Document& document, std::uint32_t page_index, model::ObjectRef ref, const AnnotationChange& change);

// Removes annotation ref, and its popup, from page page_index.
[[nodiscard]] Result<void> remove_annotation(Document& document, std::uint32_t page_index, model::ObjectRef ref);

}  // namespace capriole::edit
